// Package hypertext serves the survey pages. Its routes are generated by
// muxt from pages.gohtml. Two kinds of form are rendered by jsonhandler:
// the one authors use to write a survey, from a fixed schema, and the one
// respondents fill in, from a schema built out of the survey they open.
package hypertext

import (
	"context"
	"crypto/sha256"
	"encoding/json/jsontext"
	"errors"
	"fmt"
	"html/template"
	"log/slog"
	"net/http"
	"net/url"
	"sync"

	"github.com/crhntr/jsonschema/jsonhandler"

	"github.com/crhntr/jsonschema/examples/surveys/internal/store"
	"github.com/crhntr/jsonschema/examples/surveys/internal/survey"
	"github.com/crhntr/jsonschema/examples/surveys/schema"
)

//go:generate go tool muxt generate --use-receiver-type=Server --output-htmx

// Server is the routes receiver.
type Server struct {
	store *store.Store
	log   *slog.Logger

	// definition is the form authors write surveys with.
	definition *jsonhandler.Handler

	// answers holds the form for each survey definition seen lately, by
	// the hash of the definition, so a busy survey does not rebuild its
	// schema and form handler for every respondent.
	mu      sync.Mutex
	answers map[[sha256.Size]byte]*answerForm
}

// answerForm is what a survey needs to be taken: its definition and the
// form handler for the answers.
type answerForm struct {
	def     survey.Definition
	handler *jsonhandler.Handler
}

// maxCached is how many answer forms are kept before the cache starts over.
const maxCached = 256

// New returns a Server keeping its surveys in s.
func New(ctx context.Context, s *store.Store, log *slog.Logger) (*Server, error) {
	h, err := jsonhandler.New(ctx, schema.Definition())
	if err != nil {
		return nil, fmt.Errorf("survey form: %w", err)
	}
	h.ID, h.SubmitLabel, h.Outline = "survey", "Save survey", true
	return &Server{store: s, log: log, definition: h, answers: map[[sha256.Size]byte]*answerForm{}}, nil
}

// Routes registers the pages and the form stylesheet.
func Routes(mux *http.ServeMux, s *Server) TemplateRoutePaths {
	paths := TemplateRoutes(mux, s)
	mux.HandleFunc("GET /jsonform.css", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		_, _ = w.Write(jsonhandler.Stylesheet())
	})
	return paths
}

// Layout is what every page's frame shows. Public pages, which
// respondents see, have no navigation to the authors' pages.
type Layout struct {
	Title  string
	Public bool
}

// FormPage is a page that is mostly a form.
type FormPage struct {
	Layout
	Heading     string
	Description string
	Form        template.HTML
}

// FormResponse is the answer to a post of a form: the form again (after an
// edit, or with errors), or where to go after it was saved.
type FormResponse struct {
	FormPage
	Location string
	status   int
}

// StatusCode is 422 for a form with errors, otherwise 200.
func (r FormResponse) StatusCode() int {
	if r.status == 0 {
		return http.StatusOK
	}
	return r.status
}

// Home lists the surveys.
type Home struct {
	Layout
	Surveys []store.Entry
}

// Home shows every survey, with links to take it, see its results, and
// edit it.
func (s *Server) Home(_ context.Context) (Home, error) {
	entries, err := s.store.List()
	if err != nil {
		return Home{}, s.fail(err)
	}
	return Home{Layout: Layout{Title: "Surveys"}, Surveys: entries}, nil
}

// -- Writing a survey -------------------------------------------------

// editSpec says which survey a definition form is for: none (a new one)
// or the one named.
type editSpec struct {
	name string
}

func (e editSpec) action() string {
	if e.name == "" {
		return "/surveys/new/form"
	}
	return "/surveys/" + e.name + "/edit/form"
}

// NewSurvey shows an empty definition form.
func (s *Server) NewSurvey(ctx context.Context) (FormPage, error) {
	return s.definitionPage(ctx, editSpec{}, nil)
}

// SubmitNewSurvey applies an edit to the new survey's form, or creates it.
func (s *Server) SubmitNewSurvey(ctx context.Context, form url.Values) (FormResponse, error) {
	return s.submitDefinition(ctx, editSpec{}, form)
}

// ValidateNewSurvey checks the new survey's form as it is typed.
func (s *Server) ValidateNewSurvey(ctx context.Context, form url.Values) (template.HTML, error) {
	return s.validateDefinition(ctx, nil, form)
}

// EditSurvey shows the definition form for a survey.
func (s *Server) EditSurvey(ctx context.Context, name string) (FormPage, error) {
	def, err := s.store.Get(name)
	if err != nil {
		return FormPage{}, s.fail(err)
	}
	return s.definitionPage(ctx, editSpec{name: name}, def)
}

// SubmitEditSurvey applies an edit to the survey's form, or saves it.
func (s *Server) SubmitEditSurvey(ctx context.Context, name string, form url.Values) (FormResponse, error) {
	if _, err := s.store.Get(name); err != nil {
		return FormResponse{}, s.fail(err)
	}
	return s.submitDefinition(ctx, editSpec{name: name}, form)
}

// ValidateEditSurvey checks the survey's form as it is typed.
func (s *Server) ValidateEditSurvey(ctx context.Context, name string, form url.Values) (template.HTML, error) {
	def, err := s.store.Get(name)
	if err != nil {
		return "", s.fail(err)
	}
	return s.validateDefinition(ctx, def, form)
}

// DeleteSurvey removes a survey and its responses.
func (s *Server) DeleteSurvey(name string) error {
	return s.fail(s.store.Delete(name))
}

func (s *Server) definitionPage(ctx context.Context, e editSpec, def jsontext.Value) (FormPage, error) {
	f, err := s.definition.WithValue(def).Form(ctx)
	if err != nil {
		return FormPage{}, s.fail(err)
	}
	return s.renderDefinition(e, f, def)
}

func (s *Server) renderDefinition(e editSpec, f *jsonhandler.Form, def jsontext.Value) (FormPage, error) {
	html, err := f.WithActions(e.action(), e.action()+"/validate").HTML()
	if err != nil {
		return FormPage{}, s.fail(err)
	}
	heading := "New survey"
	if e.name != "" {
		heading = "Edit survey"
	}
	return FormPage{Layout: Layout{Title: heading}, Heading: heading, Form: html}, nil
}

func (s *Server) submitDefinition(ctx context.Context, e editSpec, form url.Values) (FormResponse, error) {
	var current jsontext.Value
	if e.name != "" {
		current, _ = s.store.Get(e.name) // the caller checked it exists
	}
	f, err := s.definition.WithValue(current).SubmitForm(ctx, form)
	if err != nil {
		return FormResponse{}, s.fail(err)
	}
	if f.Valid {
		name, err := s.saveDefinition(e, f.Value)
		if err == nil {
			return FormResponse{Location: "/surveys/" + name + "/results"}, nil
		}
		f.Reject(s.fail(err))
	}
	page, err := s.renderDefinition(e, f, current)
	return FormResponse{FormPage: page, status: f.StatusCode()}, err
}

// saveDefinition stores a valid definition, after checking that a form can
// be made from it, and returns the survey's name.
func (s *Server) saveDefinition(e editSpec, v jsontext.Value) (string, error) {
	def, err := survey.Parse(v)
	if err != nil {
		return "", err
	}
	if _, err := def.Schema(); err != nil {
		return "", message("These questions cannot make a form: " + err.Error() + ".")
	}
	name := e.name
	if name == "" {
		if name = survey.Slug(def.Title); name == "" {
			return "", message("The title needs some letters or digits, to make a web address from.")
		}
		err = s.store.Create(name, v)
	} else {
		err = s.store.Update(name, v)
	}
	if errors.Is(err, store.ErrExists) {
		return "", message(fmt.Sprintf("There is already a survey called %q. Give this one a different title.", name))
	}
	return name, err
}

func (s *Server) validateDefinition(ctx context.Context, def jsontext.Value, form url.Values) (template.HTML, error) {
	f, err := s.definition.WithValue(def).Validate(ctx, form)
	if err != nil {
		return "", s.fail(err)
	}
	html, err := f.ValidationHTML()
	return html, s.fail(err)
}

// -- Taking a survey --------------------------------------------------

// answerFormFor returns the form for the survey with the definition def.
func (s *Server) answerFormFor(ctx context.Context, def jsontext.Value) (*answerForm, error) {
	key := sha256.Sum256(def)
	s.mu.Lock()
	cached, ok := s.answers[key]
	s.mu.Unlock()
	if ok {
		return cached, nil
	}
	d, err := survey.Parse(def)
	if err != nil {
		return nil, err
	}
	doc, err := d.Schema()
	if err != nil {
		return nil, err
	}
	h, err := jsonhandler.New(ctx, doc)
	if err != nil {
		return nil, err
	}
	h.ID, h.SubmitLabel = "answers", "Send answers"
	// A respondent has no use for raw JSON.
	h.NoJSON = true
	made := &answerForm{def: d, handler: h}
	s.mu.Lock()
	if len(s.answers) >= maxCached {
		clear(s.answers)
	}
	s.answers[key] = made
	s.mu.Unlock()
	return made, nil
}

func (s *Server) answerFormNamed(ctx context.Context, name string) (*answerForm, error) {
	raw, err := s.store.Get(name)
	if err != nil {
		return nil, s.fail(err)
	}
	a, err := s.answerFormFor(ctx, raw)
	if err != nil {
		return nil, s.fail(fmt.Errorf("survey %s: %w", name, err))
	}
	return a, nil
}

func answerAction(name string) string { return "/s/" + name + "/form" }

// Take shows the form for answering a survey.
func (s *Server) Take(ctx context.Context, name string) (FormPage, error) {
	a, err := s.answerFormNamed(ctx, name)
	if err != nil {
		return FormPage{}, err
	}
	f, err := a.handler.Form(ctx)
	if err != nil {
		return FormPage{}, s.fail(err)
	}
	return s.renderAnswers(name, a, f)
}

func (s *Server) renderAnswers(name string, a *answerForm, f *jsonhandler.Form) (FormPage, error) {
	html, err := f.WithActions(answerAction(name), answerAction(name)+"/validate").HTML()
	if err != nil {
		return FormPage{}, s.fail(err)
	}
	return FormPage{
		Layout:      Layout{Title: a.def.Title, Public: true},
		Heading:     a.def.Title,
		Description: a.def.Description,
		Form:        html,
	}, nil
}

// SubmitAnswers applies an edit to the answers form, or records the
// answers when they are complete.
func (s *Server) SubmitAnswers(ctx context.Context, name string, form url.Values) (FormResponse, error) {
	a, err := s.answerFormNamed(ctx, name)
	if err != nil {
		return FormResponse{}, err
	}
	f, err := a.handler.SubmitForm(ctx, form)
	if err != nil {
		return FormResponse{}, s.fail(err)
	}
	if f.Valid {
		err := s.store.AddResponse(name, f.Value)
		if err == nil {
			return FormResponse{Location: "/s/" + name + "/thanks"}, nil
		}
		f.Reject(s.fail(err))
	}
	page, err := s.renderAnswers(name, a, f)
	return FormResponse{FormPage: page, status: f.StatusCode()}, err
}

// ValidateAnswers checks the answers as they are typed.
func (s *Server) ValidateAnswers(ctx context.Context, name string, form url.Values) (template.HTML, error) {
	a, err := s.answerFormNamed(ctx, name)
	if err != nil {
		return "", err
	}
	f, err := a.handler.Validate(ctx, form)
	if err != nil {
		return "", s.fail(err)
	}
	html, err := f.ValidationHTML()
	return html, s.fail(err)
}

// Thanks is shown after answers were sent.
type Thanks struct {
	Layout
	Name  string
	Title string
}

// Thanks thanks a respondent.
func (s *Server) Thanks(_ context.Context, name string) (Thanks, error) {
	raw, err := s.store.Get(name)
	if err != nil {
		return Thanks{}, s.fail(err)
	}
	def, err := survey.Parse(raw)
	if err != nil {
		return Thanks{}, s.fail(err)
	}
	return Thanks{Layout: Layout{Title: "Thank you", Public: true}, Name: name, Title: def.Title}, nil
}

// -- Results ----------------------------------------------------------

// ResultsPage summarizes the answers to a survey.
type ResultsPage struct {
	Layout
	Name      string
	Title     string
	Responses int
	Results   []survey.Result
}

// Results shows how people answered each question.
func (s *Server) Results(_ context.Context, name string) (ResultsPage, error) {
	raw, err := s.store.Get(name)
	if err != nil {
		return ResultsPage{}, s.fail(err)
	}
	def, err := survey.Parse(raw)
	if err != nil {
		return ResultsPage{}, s.fail(err)
	}
	responses, err := s.store.Responses(name)
	if err != nil {
		return ResultsPage{}, s.fail(err)
	}
	return ResultsPage{
		Layout:    Layout{Title: def.Title + " results"},
		Name:      name,
		Title:     def.Title,
		Responses: len(responses),
		Results:   def.Summarize(responses),
	}, nil
}
